import * as THREE from 'three'

export const WORLD = 240
export const WATER_LEVEL = 0

export function smoothstep(a,b,x){...}
const clamp = ...

export function heightAt(x, z) {
  const az = Math.abs(z)
  const wall = 26 * Math.pow(smoothstep(10, 118, az), 1.7)
  const bed = -2.8 * Math.exp(-(z*z)/(2*15*15))
  let hills = 1.5*Math.sin(x*0.055)*Math.cos(z*0.07)
            + 0.8*Math.sin(x*0.13+2.1)*Math.sin(z*0.16+0.7)
            + 0.35*Math.sin(x*0.31+4.2)*Math.cos(z*0.27)
  hills *= 0.25 + 0.75*smoothstep(12, 50, az)
  // big rolling hill on north bank
  const hill = 6.5*Math.exp(-((x-52)**2 + (z+46)**2)/1400)
  const hill2 = 5*Math.exp(-((x+58)**2 + (z-58)**2)/1200)
  let h = wall + bed + hills + hill + hill2
  // flatten spawn meadow
  const meadow = Math.exp(-(((x-8)**2 + (z-30)**2))/900)
  h = THREE.MathUtils.lerp(h, 2.2 + 0.15*Math.sin(x*0.1), meadow*0.85)
  return h
}
```
