uniform float uTime; uniform vec3 uSunDir; uniform vec3 uShallow; uniform vec3 uDeep; uniform vec3 uSunColor;
varying vec3 vWorld;
#include <fog_pars_fragment>
void main(){
  vec3 viewDir = normalize(cameraPosition - vWorld);
  float w1 = sin(vWorld.x*0.55 + uTime*0.9);
  float w2 = sin(vWorld.z*0.8 - uTime*1.1 + vWorld.x*0.2);
  float w3 = sin((vWorld.x+vWorld.z)*1.6 + uTime*1.7);
  vec3 n = normalize(vec3(0.08*w1 + 0.04*w3, 1.0, 0.07*w2 + 0.04*w3));
  float fres = pow(1.0 - max(dot(viewDir, n),0.0), 3.0);
  vec3 col = mix(uDeep, uShallow, fres*0.9 + 0.15);
  // sun specular
  vec3 h = normalize(uSunDir + viewDir);
  float spec = pow(max(dot(n,h),0.0), 120.0) * 1.4;
  // sparkle
  float sparkle = pow(max(dot(n, h),0.0), 600.0)*2.0;
  col += uSunColor * (spec + sparkle);
  // foam-ish bright lines near banks approximated by wave crest
  float crest = smoothstep(0.75, 0.98, w1*0.5+w2*0.5);
  col += vec3(0.10,0.16,0.15) * crest * 0.5;
  float alpha = mix(0.72, 0.94, fres);
  gl_FragColor = vec4(col, alpha);
  #include <fog_fragment>
}
