import * as THREE from 'three'

export const WATER_LEVEL = 0
export const WORLD_SIZE = 420
const SEGMENTS = 220

const clamp = THREE.MathUtils.clamp
const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1)
  return t * t * (3 - 2 * t)
}

// Height field for the valley: a river down the middle, gentle banks,
// rolling meadow, and steep wooded walls that close the horizon.
export function heightAt(x, z) {
  const az = Math.abs(z)
  const bed = -2.45 * Math.exp(-(z * z) / (2 * 8.5 * 8.5))
  const wallZ = 27 * Math.pow(smoothstep(9, 168, az), 1.85)
  const wallX = 32 * Math.pow(smoothstep(155, 209, Math.abs(x)), 1.45)

  let hills = 1.75 * Math.sin(x * 0.052) * Math.cos(z * 0.061)
    + 0.9 * Math.sin(x * 0.117 + 2.1) * Math.sin(z * 0.143 + 0.7)
    + 0.4 * Math.sin(x * 0.27 + 4.2) * Math.cos(z * 0.23)
  hills *= 0.22 + 0.78 * smoothstep(11, 45, az)

  const knoll = 7.5 * Math.exp(-(((x - 55) ** 2) + ((z + 58) ** 2)) / 1500)
  const knoll2 = 5.5 * Math.exp(-(((x + 62) ** 2) + ((z - 55) ** 2)) / 1200)

  let h = bed + wallZ + wallX + hills + knoll + knoll2

  // A soft meadow shelf where the player and the cottages live.
  const meadow = Math.exp(-(((x - 10) ** 2) + ((z - 34) ** 2)) / 760)
  h = THREE.MathUtils.lerp(h, 2.15 + 0.2 * Math.sin(x * 0.12) * Math.cos(z * 0.1), meadow * 0.88)
  return h
}

export function normalAt(x, z, eps = 0.7) {
  const hL = heightAt(x - eps, z)
  const hR = heightAt(x + eps, z)
  const hD = heightAt(x, z - eps)
  const hU = heightAt(x, z + eps)
  return new THREE.Vector3(hL - hR, 2 * eps, hD - hU).normalize()
}

export function slopeAt(x, z) {
  return 1 - normalAt(x, z).y
}

function mulberry32(seed) {
  return function () {
    seed |= 0
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function makeGrassTexture() {
  const size = 512
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = size
  const ctx = canvas.getContext('2d')
  ctx.fillStyle = '#f2f5ea'
  ctx.fillRect(0, 0, size, size)

  const rand = mulberry32(7)
  // Soft mottling so large grass areas never look like flat paint.
  for (let i = 0; i < 260; i++) {
    const r = 12 + rand() * 46
    ctx.fillStyle = `rgba(${120 + rand() * 40},${150 + rand() * 45},${100 + rand() * 35},${0.05 + rand() * 0.09})`
    ctx.beginPath()
    ctx.arc(rand() * size, rand() * size, r, 0, Math.PI * 2)
    ctx.fill()
  }
  // Fine blade speckles give the ground some bite up close.
  for (let i = 0; i < 5200; i++) {
    const x = rand() * size
    const y = rand() * size
    const len = 2 + rand() * 6
    const shade = 90 + Math.floor(rand() * 110)
    ctx.strokeStyle = `rgba(${shade},${shade + 24},${shade - 10},${0.16 + rand() * 0.22})`
    ctx.lineWidth = 0.7 + rand() * 0.8
    ctx.beginPath()
    ctx.moveTo(x, y)
    ctx.lineTo(x + (rand() - 0.5) * 2, y - len)
    ctx.stroke()
  }
  const texture = new THREE.CanvasTexture(canvas)
  texture.wrapS = texture.wrapT = THREE.RepeatWrapping
  texture.repeat.set(86, 86)
  texture.colorSpace = THREE.SRGBColorSpace
  texture.anisotropy = 8
  return texture
}

function buildTerrain() {
  const geometry = new THREE.PlaneGeometry(WORLD_SIZE, WORLD_SIZE, SEGMENTS, SEGMENTS)
  geometry.rotateX(-Math.PI / 2)

  const pos = geometry.attributes.position
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i)
    const z = pos.getZ(i)
    pos.setY(i, heightAt(x, z))
  }
  geometry.computeVertexNormals()

  const normals = geometry.attributes.normal
  const colors = new Float32Array(pos.count * 3)
  const grassA = new THREE.Color('#5aad3f')
  const grassB = new THREE.Color('#8ad15a')
  const grassC = new THREE.Color('#3f8a39')
  const sand = new THREE.Color('#e3cf94')
  const rock = new THREE.Color('#8f8b78')
  const deep = new THREE.Color('#5d7d52')
  const tmp = new THREE.Color()

  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i)
    const y = pos.getY(i)
    const z = pos.getZ(i)
    const slope = clamp(1 - normals.getY(i), 0, 1)

    const patch = 0.5 + 0.5 * Math.sin(x * 0.043 + 1.2) * Math.sin(z * 0.037 + 0.4)
    const fleck = 0.5 + 0.5 * Math.sin(x * 0.31 + z * 0.17 + 2.2)
    tmp.copy(grassA).lerp(grassB, patch * 0.75 + fleck * 0.25).lerp(grassC, 0.28 * fleck)

    if (slope > 0.22) tmp.lerp(rock, smoothstep(0.22, 0.62, slope))
    if (y < 1.1) tmp.lerp(sand, smoothstep(1.1, 0.15, y))
    if (y < -0.15) tmp.lerp(deep, smoothstep(-0.15, -1.6, y) * 0.8)

    colors[i * 3] = tmp.r
    colors[i * 3 + 1] = tmp.g
    colors[i * 3 + 2] = tmp.b
  }
  geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3))

  const material = new THREE.MeshStandardMaterial({
    map: makeGrassTexture(),
    vertexColors: true,
    roughness: 0.94,
    metalness: 0,
  })

  const mesh = new THREE.Mesh(geometry, material)
  mesh.receiveShadow = true
  mesh.name = 'terrain'
  return mesh
}

function buildWater() {
  const geometry = new THREE.PlaneGeometry(WORLD_SIZE, WORLD_SIZE, 1, 1)
  geometry.rotateX(-Math.PI / 2)

  const material = new THREE.ShaderMaterial({
    uniforms: THREE.UniformsUtils.merge([
      THREE.UniformsLib.fog,
      {
        uTime: { value: 0 },
        uSunDir: { value: new THREE.Vector3(0.55, 0.62, 0.42).normalize() },
        uShallow: { value: new THREE.Color('#78d8cf') },
        uDeep: { value: new THREE.Color('#1d7f96') },
        uSunColor: { value: new THREE.Color('#fff2c8') },
      },
    ]),
    vertexShader: /* glsl */ `
      varying vec3 vWorld;
      #include <fog_pars_vertex>
      void main() {
        vec4 world = modelMatrix * vec4(position, 1.0);
        vWorld = world.xyz;
        vec4 mvPosition = viewMatrix * world;
        gl_Position = projectionMatrix * mvPosition;
        #include <fog_vertex>
      }
    `,
    fragmentShader: /* glsl */ `
      uniform float uTime;
      uniform vec3 uSunDir;
      uniform vec3 uShallow;
      uniform vec3 uDeep;
      uniform vec3 uSunColor;
      varying vec3 vWorld;
      #include <fog_pars_fragment>
      void main() {
        vec3 viewDir = normalize(cameraPosition - vWorld);
        float w1 = sin(vWorld.x * 0.55 + uTime * 0.9);
        float w2 = sin(vWorld.z * 0.8 - uTime * 1.15 + vWorld.x * 0.18);
        float w3 = sin((vWorld.x + vWorld.z) * 1.7 + uTime * 1.9);
        vec3 n = normalize(vec3(
          0.075 * w1 + 0.035 * w3,
          1.0,
          0.065 * w2 + 0.035 * w3
        ));
        float fresnel = pow(1.0 - max(dot(viewDir, n), 0.0), 3.0);
        vec3 color = mix(uDeep, uShallow, clamp(fresnel * 0.95 + 0.14, 0.0, 1.0));
        vec3 halfDir = normalize(uSunDir + viewDir);
        float spec = pow(max(dot(n, halfDir), 0.0), 120.0) * 1.6;
        float sparkle = pow(max(dot(n, halfDir), 0.0), 700.0) * 2.4;
        color += uSunColor * (spec + sparkle);
        float crest = smoothstep(0.8, 0.99, w1 * 0.5 + w2 * 0.5);
        color += vec3(0.16, 0.24, 0.21) * crest;
        float alpha = mix(0.74, 0.94, fresnel);
        gl_FragColor = vec4(color, alpha);
        #include <fog_fragment>
      }
    `,
    transparent: true,
    depthWrite: false,
    fog: true,
    side: THREE.DoubleSide,
  })

  const mesh = new THREE.Mesh(geometry, material)
  mesh.position.y = WATER_LEVEL
  mesh.renderOrder = 1
  mesh.name = 'water'
  return mesh
}

export function createWorld(scene) {
  const terrain = buildTerrain()
  scene.add(terrain)

  const water = buildWater()
  scene.add(water)

  return {
    terrain,
    water,
    update(time) {
      water.material.uniforms.uTime.value = time
    },
  }
}

import * as THREE from 'three'
import { heightAt, slopeAt, WATER_LEVEL } from './terrain.js'

const clamp = THREE.MathUtils.clamp
const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1)
  return t * t * (3 - 2 * t)
}

const SUN_DIR = new THREE.Vector3(-0.38, 0.56, -0.58).normalize()

export const BRIDGE = {
  x: -6,
  halfWidth: 2.5,
  deckHeight: 1.35,
  rampStart: 15.5,
  rampEnd: 20.5,
  endHeight: 0.35,
}

export function bridgeDeckAt(x, z) {
  if (Math.abs(x - BRIDGE.x) > BRIDGE.halfWidth) return null
  const az = Math.abs(z)
  if (az > BRIDGE.rampEnd) return null
  const t = clamp((az - BRIDGE.rampStart) / (BRIDGE.rampEnd - BRIDGE.rampStart), 0, 1)
  return BRIDGE.deckHeight - (BRIDGE.deckHeight - BRIDGE.endHeight) * t
}

function mulberry32(seed) {
  return function () {
    seed |= 0
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const BOX = new THREE.BoxGeometry(1, 1, 1)

function box(w, h, d, material) {
  const mesh = new THREE.Mesh(BOX, material)
  mesh.scale.set(w, h, d)
  return mesh
}

function shadowed(mesh) {
  mesh.castShadow = true
  mesh.receiveShadow = true
  return mesh
}

function makeSky(scene) {
  const uniforms = {
    uTop: { value: new THREE.Color('#3f8fdd') },
    uHorizon: { value: new THREE.Color('#ffe4b5') },
    uHaze: { value: new THREE.Color('#cfeaf4') },
    uSunDir: { value: SUN_DIR.clone() },
    uSunColor: { value: new THREE.Color('#fff3cf') },
  }
  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: /* glsl */ `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 uTop;
      uniform vec3 uHorizon;
      uniform vec3 uHaze;
      uniform vec3 uSunDir;
      uniform vec3 uSunColor;
      varying vec3 vDir;
      void main() {
        vec3 dir = normalize(vDir);
        float h = clamp(dir.y, 0.0, 1.0);
        vec3 col = mix(uHorizon, uTop, pow(h, 0.5));
        col = mix(col, uHaze, smoothstep(0.0, 0.28, h) * 0.35);
        float sunAmount = max(dot(dir, uSunDir), 0.0);
        float glow = pow(sunAmount, 5.0) * 0.30;
        float disc = smoothstep(0.9975, 0.9990, sunAmount) * 1.4;
        col += uSunColor * (glow + disc);
        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
  })

  const sky = new THREE.Mesh(new THREE.SphereGeometry(600, 40, 24), material)
  sky.renderOrder = -2
  scene.add(sky)

  // Soft sun bloom behind the disc.
  const c = document.createElement('canvas')
  c.width = c.height = 256
  const ctx = c.getContext('2d')
  const grad = ctx.createRadialGradient(128, 128, 8, 128, 128, 128)
  grad.addColorStop(0, 'rgba(255,250,226,0.95)')
  grad.addColorStop(0.18, 'rgba(255,236,180,0.55)')
  grad.addColorStop(0.5, 'rgba(255,214,140,0.16)')
  grad.addColorStop(1, 'rgba(255,200,120,0)')
  ctx.fillStyle = grad
  ctx.fillRect(0, 0, 256, 256)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: tex,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
  }))
  sprite.position.copy(SUN_DIR).multiplyScalar(470)
  sprite.scale.setScalar(130)
  scene.add(sprite)

  return sky
}

function makeClouds(scene, rng) {
  const geometry = new THREE.IcosahedronGeometry(1, 1)
  const material = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 1,
    metalness: 0,
    flatShading: true,
    transparent: true,
    opacity: 0.94,
  })
  const puffs = []
  const cloudCenters = []
  for (let i = 0; i < 16; i++) {
    const angle = rng() * Math.PI * 2
    const radius = 90 + rng() * 120
    const cx = Math.cos(angle) * radius
    const cz = Math.sin(angle) * radius
    const cy = 56 + rng() * 34
    const count = 4 + Math.floor(rng() * 4)
    cloudCenters.push({ cx, cy, cz })
    for (let j = 0; j < count; j++) {
      puffs.push({
        x: cx + (rng() - 0.5) * 22,
        y: cy + (rng() - 0.5) * 5,
        z: cz + (rng() - 0.5) * 12,
        sx: 5 + rng() * 7,
        sy: 2.6 + rng() * 2.6,
        sz: 5 + rng() * 6,
      })
    }
  }
  const mesh = new THREE.InstancedMesh(geometry, material, puffs.length)
  const dummy = new THREE.Object3D()
  puffs.forEach((p, i) => {
    dummy.position.set(p.x, p.y, p.z)
    dummy.scale.set(p.sx, p.sy, p.sz)
    dummy.rotation.set(rng() * 0.4, rng() * Math.PI, rng() * 0.4)
    dummy.updateMatrix()
    mesh.setMatrixAt(i, dummy.matrix)
  })
  mesh.instanceMatrix.needsUpdate = true
  mesh.frustumCulled = false
  scene.add(mesh)
  return { mesh, centers: cloudCenters }
}

function makeTrees(root, rng, blocked) {
  const trunkGeo = new THREE.CylinderGeometry(0.26, 0.44, 3.4, 6)
  trunkGeo.translate(0, 1.7, 0)
  const leafGeo = new THREE.IcosahedronGeometry(1.25, 0)
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x7a5230, roughness: 1 })
  const leafMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95, flatShading: true })

  const trees = []
  let guard = 0
  while (trees.length < 120 && guard++ < 4000) {
    const x = (rng() - 0.5) * 190
    const z = (rng() - 0.5) * 190
    const h = heightAt(x, z)
    if (h < 1.2 || h > 30) continue
    if (slopeAt(x, z) > 0.55) continue
    if (Math.abs(z) < 12) continue
    if (blocked(x, z, 7.5)) continue
    if (Math.hypot(x - 10, z - 34) < 8) continue
    trees.push({ x, z, h, s: 0.85 + rng() * 0.7, rot: rng() * Math.PI * 2 })
  }
  // A couple of hero trees framing the meadow.
  trees.push({ x: -4, z: 45, h: heightAt(-4, 45), s: 1.7, rot: 0.6 })
  trees.push({ x: 33, z: 30, h: heightAt(33, 30), s: 1.45, rot: 2.1 })

  const trunkMesh = new THREE.InstancedMesh(trunkGeo, trunkMat, trees.length)
  trunkMesh.castShadow = true
  trunkMesh.receiveShadow = true
  const leaves = []
  const palette = ['#3d8b33', '#4f9f3d', '#61b34a', '#74c356', '#2f7a2c'].map(c => new THREE.Color(c))
  const dummy = new THREE.Object3D()
  trees.forEach((t, i) => {
    dummy.position.set(t.x, t.h, t.z)
    dummy.rotation.set(0, t.rot, 0)
    dummy.scale.setScalar(t.s)
    dummy.updateMatrix()
    trunkMesh.setMatrixAt(i, dummy.matrix)

    const clusters = 2 + Math.floor(rng() * 2)
    for (let c = 0; c < clusters; c++) {
      const angle = rng() * Math.PI * 2
      const radius = c === 0 ? 0 : 0.85 * t.s
      leaves.push({
        x: t.x + Math.cos(angle) * radius,
        y: t.h + (3.15 + rng() * 0.55 + (c === 0 ? 0.35 : 0)) * t.s,
        z: t.z + Math.sin(angle) * radius,
        s: (0.9 + rng() * 0.45) * t.s * (c === 0 ? 1.15 : 0.9),
        color: palette[Math.floor(rng() * palette.length)],
        rot: rng() * Math.PI,
      })
    }
  })
  trunkMesh.instanceMatrix.needsUpdate = true
  root.add(trunkMesh)

  const leafMesh = new THREE.InstancedMesh(leafGeo, leafMat, leaves.length)
  leafMesh.castShadow = true
  leafMesh.receiveShadow = true
  leaves.forEach((l, i) => {
    dummy.position.set(l.x, l.y, l.z)
    dummy.rotation.set(l.rot * 0.4, l.rot, l.rot * 0.2)
    dummy.scale.set(l.s * 1.15, l.s * 0.92, l.s * 1.15)
    dummy.updateMatrix()
    leafMesh.setMatrixAt(i, dummy.matrix)
    leafMesh.setColorAt(i, l.color)
  })
  leafMesh.instanceMatrix.needsUpdate = true
  if (leafMesh.instanceColor) leafMesh.instanceColor.needsUpdate = true
  root.add(leafMesh)

  return trees
}

function makeBushes(root, rng, blocked) {
  const geo = new THREE.IcosahedronGeometry(0.95, 0)
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, flatShading: true })
  const palette = ['#3c8a34', '#4d9c3c', '#5aab44', '#347c2f'].map(c => new THREE.Color(c))
  const items = []
  let guard = 0
  while (items.length < 130 && guard++ < 2000) {
    const x = (rng() - 0.5) * 170
    const z = (rng() - 0.5) * 170
    const h = heightAt(x, z)
    if (h < 0.8 || h > 18) continue
    if (slopeAt(x, z) > 0.5) continue
    if (blocked(x, z, 3.2)) continue
    items.push({ x, z, h, s: 0.5 + rng() * 0.85, rot: rng() * Math.PI })
  }
  const mesh = new THREE.InstancedMesh(geo, mat, items.length)
  mesh.castShadow = true
  mesh.receiveShadow = true
  const dummy = new THREE.Object3D()
  items.forEach((it, i) => {
    dummy.position.set(it.x, it.h + it.s * 0.45, it.z)
    dummy.rotation.set(it.rot * 0.3, it.rot, 0)
    dummy.scale.set(it.s * 1.25, it.s * 0.8, it.s * 1.25)
    dummy.updateMatrix()
    mesh.setMatrixAt(i, dummy.matrix)
    mesh.setColorAt(i, palette[Math.floor(rng() * palette.length)])
  })
  mesh.instanceMatrix.needsUpdate = true
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true
  root.add(mesh)
}

function makeRocks(root, rng) {
  const geo = new THREE.DodecahedronGeometry(0.85, 0)
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95, flatShading: true })
  const items = []
  let guard = 0
  while (items.length < 90 && guard++ < 1500) {
    const x = (rng() - 0.5) * 170
    const z = (rng() - 0.5) * 170
    const h = heightAt(x, z)
    const nearRiver = Math.abs(z) < 26
    if (h < -0.4 || h > 20) continue
    if (!nearRiver && rng() > 0.35) continue
    if (Math.hypot(x - 10, z - 34) < 5) continue
    items.push({ x, z, h, s: 0.5 + rng() * 1.25, rot: rng() * Math.PI })
  }
  const mesh = new THREE.InstancedMesh(geo, mat, items.length)
  mesh.castShadow = true
  mesh.receiveShadow = true
  const dummy = new THREE.Object3D()
  const grey = new THREE.Color('#9d9a8c')
  items.forEach((it, i) => {
    dummy.position.set(it.x, it.h + it.s * 0.25, it.z)
    dummy.rotation.set(rng() * 0.5, it.rot, rng() * 0.5)
    dummy.scale.set(it.s * 1.2, it.s * 0.8, it.s * 1.1)
    dummy.updateMatrix()
    mesh.setMatrixAt(i, dummy.matrix)
    mesh.setColorAt(i, grey.clone().offsetHSL(0, 0, (rng() - 0.5) * 0.08))
  })
  mesh.instanceMatrix.needsUpdate = true
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true
  root.add(mesh)
}

function makeGrass(root, rng, blocked) {
  const geo = new THREE.ConeGeometry(0.16, 1, 3)
  geo.translate(0, 0.5, 0)
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, flatShading: true })
  const palette = ['#79c455', '#8ed166', '#67b44a', '#a3da74'].map(c => new THREE.Color(c))
  const count = 3400
  const mesh = new THREE.InstancedMesh(geo, mat, count)
  mesh.receiveShadow = true
  const dummy = new THREE.Object3D()
  let placed = 0
  let guard = 0
  while (placed < count && guard++ < count * 8) {
    const x = (rng() - 0.5) * 155
    const z = (rng() - 0.5) * 155
    const h = heightAt(x, z)
    if (h < 0.9 || h > 14) continue
    if (slopeAt(x, z) > 0.4) continue
    if (blocked(x, z, 2.2)) continue
    const s = 0.55 + rng() * 1.15
    dummy.position.set(x, h - 0.05, z)
    dummy.rotation.set((rng() - 0.5) * 0.2, rng() * Math.PI, (rng() - 0.5) * 0.2)
    dummy.scale.set(0.8 + rng() * 0.7, s, 0.8 + rng() * 0.7)
    dummy.updateMatrix()
    mesh.setMatrixAt(placed, dummy.matrix)
    mesh.setColorAt(placed, palette[Math.floor(rng() * palette.length)])
    placed++
  }
  mesh.count = placed
  mesh.instanceMatrix.needsUpdate = true
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true
  root.add(mesh)
}

function makeFlowers(root, rng, blocked) {
  const stemGeo = new THREE.CylinderGeometry(0.035, 0.045, 0.7, 4)
  stemGeo.translate(0, 0.35, 0)
  const headGeo = new THREE.IcosahedronGeometry(0.17, 0)
  const stemMat = new THREE.MeshStandardMaterial({ color: 0x4c8f38, roughness: 1 })
  const headMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.8, flatShading: true })
  const palette = ['#ff8fb1', '#fff6df', '#ffd75e', '#c9a2ff', '#ff9f5e'].map(c => new THREE.Color(c))
  const count = 520
  const stems = new THREE.InstancedMesh(stemGeo, stemMat, count)
  const heads = new THREE.InstancedMesh(headGeo, headMat, count)
  const dummy = new THREE.Object3D()
  let placed = 0
  let guard = 0
  while (placed < count && guard++ < count * 10) {
    const x = (rng() - 0.5) * 120
    const z = (rng() - 0.5) * 120
    const h = heightAt(x, z)
    if (h < 1.4 || h > 10) continue
    if (slopeAt(x, z) > 0.35) continue
    if (blocked(x, z, 2.5)) continue
    if (Math.hypot(x - 10, z - 34) > 55) continue
    const s = 0.75 + rng() * 0.7
    dummy.position.set(x, h, z)
    dummy.rotation.set(0, rng() * Math.PI, 0)
    dummy.scale.setScalar(s)
    dummy.updateMatrix()
    stems.setMatrixAt(placed, dummy.matrix)
    heads.setMatrixAt(placed, dummy.matrix)
    heads.setColorAt(placed, palette[Math.floor(rng() * palette.length)])
    placed++
  }
  stems.count = heads.count = placed
  stems.instanceMatrix.needsUpdate = true
  heads.instanceMatrix.needsUpdate = true
  if (heads.instanceColor) heads.instanceColor.needsUpdate = true
  root.add(stems, heads)
}

function makeReeds(root, rng) {
  const geo = new THREE.BoxGeometry(0.05, 1, 0.05)
  geo.translate(0, 0.5, 0)
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1 })
  const palette = ['#8fae4e', '#a4bd5e', '#7e9c43'].map(c => new THREE.Color(c))
  const count = 320
  const mesh = new THREE.InstancedMesh(geo, mat, count)
  const dummy = new THREE.Object3D()
  let placed = 0
  let guard = 0
  while (placed < count && guard++ < 3000) {
    const x = (rng() - 0.5) * 170
    const z = 12 + rng() * 12
    const zz = rng() > 0.5 ? z : -z
    const h = heightAt(x, zz)
    if (h < -0.1 || h > 0.8) continue
    const s = 0.9 + rng() * 1.3
    dummy.position.set(x, h, zz)
    dummy.rotation.set((rng() - 0.5) * 0.15, rng() * Math.PI, (rng() - 0.5) * 0.15)
    dummy.scale.set(1, s, 1)
    dummy.updateMatrix()
    mesh.setMatrixAt(placed, dummy.matrix)
    mesh.setColorAt(placed, palette[Math.floor(rng() * palette.length)])
    placed++
  }
  mesh.count = placed
  mesh.instanceMatrix.needsUpdate = true
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true
  root.add(mesh)
}

function makePath(root, points, width, material) {
  const curve = new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(p[0], 0, p[1])))
  const steps = 90
  const positions = []
  const colors = []
  const base = new THREE.Color('#b08a5c')
  const tint = new THREE.Color()
  const left = []
  const right = []
  for (let i = 0; i <= steps; i++) {
    const t = i / steps
    const p = curve.getPoint(t)
    const tangent = curve.getTangent(t)
    const nx = -tangent.z
    const nz = tangent.x
    const len = Math.hypot(nx, nz) || 1
    const half = width * (0.85 + 0.3 * Math.sin(t * 9.1))
    const lx = p.x + (nx / len) * half
    const lz = p.z + (nz / len) * half
    const rx = p.x - (nx / len) * half
    const rz = p.z - (nz / len) * half
    left.push(new THREE.Vector3(lx, heightAt(lx, lz) + 0.09, lz))
    right.push(new THREE.Vector3(rx, heightAt(rx, rz) + 0.09, rz))
    tint.copy(base).offsetHSL(0, 0, (Math.sin(t * 13.7) + Math.sin(t * 5.3)) * 0.02)
    colors.push(tint.r, tint.g, tint.b)
  }
  for (let i = 0; i < steps; i++) {
    const l0 = left[i]
    const r0 = right[i]
    const l1 = left[i + 1]
    const r1 = right[i + 1]
    positions.push(l0.x, l0.y, l0.z, r0.x, r0.y, r0.z, l1.x, l1.y, l1.z)
    positions.push(r0.x, r0.y, r0.z, r1.x, r1.y, r1.z, l1.x, l1.y, l1.z)
    for (let k = 0; k < 2; k++) {
      const c = colors.slice(i * 3, i * 3 + 3)
      const c2 = colors.slice((i + 1) * 3, (i + 1) * 3 + 3)
      if (k === 0) colors.push(...c, ...c, ...c2)
      else colors.push(...c, ...c2, ...c2)
    }
  }
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
  geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3))
  geometry.computeVertexNormals()
  const mesh = new THREE.Mesh(geometry, material)
  mesh.receiveShadow = true
  root.add(mesh)
  return mesh
}

function makeHouse(root, rng, opts) {
  const { x, z, rot = 0, wallColor = '#f3e4c4', roofColor = '#a8493a', scale = 1, lamp = false } = opts
  const group = new THREE.Group()
  const baseY = heightAt(x, z)
  group.position.set(x, baseY, z)
  group.rotation.y = rot
  group.scale.setScalar(scale)

  const wallMat = new THREE.MeshStandardMaterial({ color: wallColor, roughness: 0.92 })
  const wallMatDark = new THREE.MeshStandardMaterial({ color: new THREE.Color(wallColor).multiplyScalar(0.86), roughness: 0.95 })
  const roofMat = new THREE.MeshStandardMaterial({ color: roofColor, roughness: 0.85 })
  const stoneMat = new THREE.MeshStandardMaterial({ color: '#9a9689', roughness: 1 })
  const woodMat = new THREE.MeshStandardMaterial({ color: '#6f4a2d', roughness: 0.95 })
  const trimMat = new THREE.MeshStandardMaterial({ color: '#f8f2e2', roughness: 0.9 })
  const glassMat = new THREE.MeshStandardMaterial({
    color: '#a9d9e6',
    roughness: 0.15,
    metalness: 0.1,
    emissive: new THREE.Color('#ffcf94'),
    emissiveIntensity: 0.25,
  })

  const w = 7
  const d = 5.6
  const wallH = 3.3
  const floorY = 0.9
  const wallTop = floorY + wallH

  const foundation = box(w + 0.7, 1.9, d + 0.7, stoneMat)
  foundation.position.y = floorY - 0.95
  shadowed(foundation)
  group.add(foundation)

  const walls = box(w, wallH, d, wallMat)
  walls.position.y = floorY + wallH / 2
  shadowed(walls)
  group.add(walls)

  // Timber corners.
  for (const sx of [-1, 1]) {
    for (const sz of [-1, 1]) {
      const post = box(0.22, wallH + 0.05, 0.22, woodMat)
      post.position.set(sx * (w / 2 - 0.02), floorY + wallH / 2, sz * (d / 2 - 0.02))
      group.add(post)
    }
  }

  // Roof: two pitched slabs plus triangular gable ends.
  const rise = 2.0
  const halfDepth = d / 2
  const angle = Math.atan2(rise, halfDepth)
  const slabLen = Math.hypot(halfDepth, rise) + 0.45
  for (const side of [-1, 1]) {
    const slab = box(w + 1.5, 0.24, slabLen, roofMat)
    slab.position.set(0, wallTop + rise / 2 - 0.03, side * halfDepth / 2)
    slab.rotation.x = side * angle
    shadowed(slab)
    group.add(slab)
  }
  const ridge = box(w + 1.6, 0.2, 0.5, roofMat)
  ridge.position.y = wallTop + rise + 0.06
  group.add(ridge)

  const gableShape = new THREE.Shape()
  gableShape.moveTo(-halfDepth, 0)
  gableShape.lineTo(halfDepth, 0)
  gableShape.lineTo(0, rise)
  gableShape.closePath()
  const gableGeo = new THREE.ShapeGeometry(gableShape)
  for (const side of [-1, 1]) {
    const gable = new THREE.Mesh(gableGeo, new THREE.MeshStandardMaterial({ color: wallColor, roughness: 0.92, side: THREE.DoubleSide }))
    gable.rotation.y = side * Math.PI / 2
    gable.position.set(side * (w / 2 + 0.01), wallTop, 0)
    gable.castShadow = true
    group.add(gable)
  }

  // Chimney.
  const chimney = box(0.85, 3.0, 0.85, new THREE.MeshStandardMaterial({ color: '#8d5a44', roughness: 1 }))
  chimney.position.set(-w / 2 + 1.3, wallTop + 0.55, -d / 2 + 1.15)
  shadowed(chimney)
  group.add(chimney)
  const cap = box(1.05, 0.18, 1.05, stoneMat)
  cap.position.set(chimney.position.x, wallTop + 2.1, chimney.position.z)
  group.add(cap)

  // Door with frame and little porch.
  const door = box(1.15, 2.05, 0.16, woodMat)
  door.position.set(0, floorY + 1.02, d / 2 + 0.05)
  group.add(door)
  const doorTrim = box(1.4, 2.3, 0.1, trimMat)
  doorTrim.position.set(0, floorY + 1.05, d / 2 + 0.01)
  group.add(doorTrim)
  const knob = new THREE.Mesh(new THREE.SphereGeometry(0.07, 8, 8), new THREE.MeshStandardMaterial({ color: '#f4c95d', metalness: 0.8, roughness: 0.3 }))
  knob.position.set(0.36, floorY + 1.0, d / 2 + 0.16)
  group.add(knob)

  const porch = box(w + 0.9, 0.2, 1.5, woodMat)
  porch.position.set(0, floorY - 0.1, d / 2 + 0.75)
  shadowed(porch)
  group.add(porch)
  const step = box(2.2, 0.35, 0.7, stoneMat)
  step.position.set(0, floorY - 0.45, d / 2 + 1.65)
  group.add(step)

  // Windows.
  const addWindow = (px, py, pz, ry = 0) => {
    const win = new THREE.Group()
    win.position.set(px, py, pz)
    win.rotation.y = ry
    const pane = box(1.15, 1.0, 0.08, glassMat)
    win.add(pane)
    const frameV = box(0.09, 1.16, 0.1, trimMat)
    const frameH = box(1.3, 0.09, 0.1, trimMat)
    const l = frameV.clone(); l.position.x = -0.61; win.add(l)
    const r = frameV.clone(); r.position.x = 0.61; win.add(r)
    const t = frameH.clone(); t.position.y = 0.54; win.add(t)
    const b = frameH.clone(); b.position.y = -0.54; win.add(b)
    const mV = box(0.06, 1.0, 0.09, trimMat); win.add(mV)
    const mH = box(1.15, 0.06, 0.09, trimMat); win.add(mH)
    const boxFlower = box(1.35, 0.3, 0.35, woodMat)
    boxFlower.position.y = -0.72
    boxFlower.position.z = 0.22
    win.add(boxFlower)
    const blooms = new THREE.Mesh(new THREE.IcosahedronGeometry(0.2, 0), new THREE.MeshStandardMaterial({ color: '#ff8fb1', roughness: 0.9 }))
    blooms.position.set(0, -0.55, 0.24)
    blooms.scale.set(3.2, 0.7, 1)
    win.add(blooms)
    win.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true } })
    group.add(win)
  }
  addWindow(-2.0, floorY + 2.1, d / 2 + 0.05)
  addWindow(2.0, floorY + 2.1, d / 2 + 0.05)
  addWindow(w / 2 + 0.05, floorY + 2.1, 0, Math.PI / 2)
  addWindow(-w / 2 - 0.05, floorY + 2.1, 0.6, -Math.PI / 2)

  // Porch lantern.
  const lampPost = box(0.12, 2.4, 0.12, woodMat)
  lampPost.position.set(w / 2 + 0.75, floorY + 1.15, d / 2 + 1.0)
  group.add(lampPost)
  const lampBox = box(0.36, 0.46, 0.36, new THREE.MeshStandardMaterial({
    color: '#ffdf9e',
    emissive: new THREE.Color('#ffb45e'),
    emissiveIntensity: 1.4,
    roughness: 0.5,
  }))
  lampBox.position.set(lampPost.position.x, floorY + 2.35, lampPost.position.z)
  group.add(lampBox)
  if (lamp) {
    const light = new THREE.PointLight(0xffb768, 7, 13, 2)
    light.position.copy(lampBox.position)
    group.add(light)
  }

  root.add(group)
  return { group, x, z, radius: 6.4 * scale, floorY, baseY }
}

function makeFence(root, rng, x1, z1, x2, z2) {
  const woodMat = new THREE.MeshStandardMaterial({ color: '#8a6239', roughness: 1 })
  const dx = x2 - x1
  const dz = z2 - z1
  const length = Math.hypot(dx, dz)
  const count = Math.max(2, Math.round(length / 1.6))
  const angle = Math.atan2(dx, dz)
  for (let i = 0; i <= count; i++) {
    const t = i / count
    const px = x1 + dx * t
    const pz = z1 + dz * t
    const h = heightAt(px, pz)
    const post = box(0.16, 0.95, 0.16, woodMat)
    post.position.set(px, h + 0.45, pz)
    post.rotation.y = rng() * 0.1
    post.castShadow = true
    root.add(post)
    if (i < count) {
      const nx = x1 + dx * (t + 0.5 / count)
      const nz = z1 + dz * (t + 0.5 / count)
      const nh = heightAt(nx, nz)
      for (const yOff of [0.32, 0.68]) {
        const rail = box(0.09, 0.1, length / count + 0.1, woodMat)
        rail.position.set(nx, nh + yOff, nz)
        rail.rotation.y = angle
        rail.castShadow = true
        root.add(rail)
      }
    }
  }
}

function makeBridge(root, rng) {
  const x = BRIDGE.x
  const woodMat = new THREE.MeshStandardMaterial({ color: 0x8a6239, roughness: 0.95 })
  const darkWood = new THREE.MeshStandardMaterial({ color: 0x6d4a2b, roughness: 1 })
  const ropeMat = new THREE.MeshStandardMaterial({ color: 0xcaa56f, roughness: 1 })

  const step = 0.58
  const zs = []
  for (let z = -BRIDGE.rampEnd + 0.3; z <= BRIDGE.rampEnd - 0.3; z += step) zs.push(z)
  const planks = new THREE.InstancedMesh(BOX, woodMat, zs.length)
  planks.castShadow = true
  planks.receiveShadow = true
  const dummy = new THREE.Object3D()
  zs.forEach((z, i) => {
    dummy.position.set(x + (rng() - 0.5) * 0.06, bridgeDeckAt(x, z) - 0.1, z)
    dummy.rotation.set(0, (rng() - 0.5) * 0.02, 0)
    dummy.scale.set(4.9, 0.2, step * 0.88)
    dummy.updateMatrix()
    planks.setMatrixAt(i, dummy.matrix)
  })
  planks.instanceMatrix.needsUpdate = true
  root.add(planks)

  // Support beams under the deck.
  for (const side of [-1, 1]) {
    for (let z = -18; z <= 18; z += 6) {
      const beam = box(0.3, 0.35, 6.2, darkWood)
      beam.position.set(x + side * 2.1, bridgeDeckAt(x, z) - 0.35, z)
      beam.castShadow = true
      root.add(beam)
    }
  }

  // Trestles down into the river.
  for (const z of [-15, -9, -3, 3, 9, 15]) {
    for (const side of [-1, 1]) {
      const leg = box(0.3, 2.4, 0.3, darkWood)
      const ground = Math.min(heightAt(x + side * 2.1, z), WATER_LEVEL)
      leg.position.set(x + side * 2.1, bridgeDeckAt(x, z) - 0.5 - 1.0 + (ground + 1.0) / 2, z)
      leg.rotation.z = side * 0.12
      leg.castShadow = true
      root.add(leg)
    }
    const cross = box(4.5, 0.2, 0.22, darkWood)
    cross.position.set(x, WATER_LEVEL + 0.35, z)
    root.add(cross)
  }

  // Railings follow the deck profile.
  const postGeo = new THREE.BoxGeometry(0.12, 1.05, 0.12)
  const railGeo = new THREE.BoxGeometry(0.09, 0.09, 1)
  const postZ = []
  for (let z = -BRIDGE.rampEnd + 0.3; z <= BRIDGE.rampEnd - 0.3; z += 2.4) postZ.push(z)
  const posts = new THREE.InstancedMesh(postGeo, darkWood, postZ.length * 2)
  posts.castShadow = true
  let pi = 0
  for (const z of postZ) {
    for (const side of [-1, 1]) {
      dummy.position.set(x + side * 2.35, bridgeDeckAt(x, z) + 0.42, z)
      dummy.rotation.set(0, 0, 0)
      dummy.scale.set(1, 1, 1)
      dummy.updateMatrix()
      posts.setMatrixAt(pi++, dummy.matrix)
    }
  }
  posts.instanceMatrix.needsUpdate = true
  root.add(posts)

  const railSegments = []
  for (let i = 0; i < postZ.length - 1; i++) {
    for (const side of [-1, 1]) {
      for (const heightOff of [0.55, 0.92]) {
        const z0 = postZ[i]
        const z1 = postZ[i + 1]
        const a = new THREE.Vector3(x + side * 2.35, bridgeDeckAt(x, z0) + heightOff, z0)
        const b = new THREE.Vector3(x + side * 2.35, bridgeDeckAt(x, z1) + heightOff, z1)
        railSegments.push({ a, b })
      }
    }
  }
  const rails = new THREE.InstancedMesh(railGeo, ropeMat, railSegments.length)
  rails.castShadow = true
  const up = new THREE.Vector3(0, 1, 0)
  railSegments.forEach((seg, i) => {
    const dir = new THREE.Vector3().subVectors(seg.b, seg.a)
    const len = dir.length()
    dummy.position.copy(seg.a).add(seg.b).multiplyScalar(0.5)
    dummy.quaternion.setFromUnitVectors(up, dir.clone().normalize())
    dummy.scale.set(1, len, 1)
    dummy.updateMatrix()
    rails.setMatrixAt(i, dummy.matrix)
  })
  rails.instanceMatrix.needsUpdate = true
  root.add(rails)

  // Lantern posts at both ends.
  for (const side of [-1, 1]) {
    const z = side * (BRIDGE.rampEnd - 0.6)
    const px = x + 2.9
    const baseH = heightAt(px, z)
    const post = box(0.18, 2.8, 0.18, darkWood)
    post.position.set(px, baseH + 1.4, z)
    post.castShadow = true
    root.add(post)
    const lamp = box(0.42, 0.5, 0.42, new THREE.MeshStandardMaterial({
      color: '#ffdf9e',
      emissive: new THREE.Color('#ffae54'),
      emissiveIntensity: 1.6,
      roughness: 0.4,
    }))
    lamp.position.set(px, baseH + 2.9, z)
    root.add(lamp)
    if (side === 1) {
      const light = new THREE.PointLight(0xffb36a, 9, 16, 2)
      light.position.copy(lamp.position)
      root.add(light)
    }
  }

  return { posts, rails }
}

function makeWindmill(root, x, z) {
  const group = new THREE.Group()
  const baseY = heightAt(x, z)
  group.position.set(x, baseY, z)

  const stone = new THREE.MeshStandardMaterial({ color: '#d9cdb2', roughness: 1 })
  const wood = new THREE.MeshStandardMaterial({ color: '#7d5634', roughness: 1 })
  const sailMat = new THREE.MeshStandardMaterial({ color: '#f5ecd8', roughness: 0.9 })

  const tower = new THREE.Mesh(new THREE.CylinderGeometry(1.9, 2.9, 9, 8), stone)
  tower.position.y = 4.5
  shadowed(tower)
  group.add(tower)

  const band = new THREE.Mesh(new THREE.CylinderGeometry(2.3, 2.45, 0.5, 8), wood)
  band.position.y = 5.6
  group.add(band)

  const cap = new THREE.Mesh(new THREE.ConeGeometry(2.5, 2.4, 8), new THREE.MeshStandardMaterial({ color: '#8d4a38', roughness: 0.9 }))
  cap.position.y = 9.9
  shadowed(cap)
  group.add(cap)

  const door = box(1.2, 2.1, 0.2, wood)
  door.position.set(0, 1.05, 2.72)
  group.add(door)
  const win = box(0.8, 0.8, 0.15, new THREE.MeshStandardMaterial({ color: '#ffe4ae', emissive: new THREE.Color('#ffb45e'), emissiveIntensity: 0.8 }))
  win.position.set(0, 6.2, 2.15)
  group.add(win)

  const hub = new THREE.Group()
  hub.position.set(0, 8.9, 2.5)
  group.add(hub)
  const axle = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, 0.6, 8), wood)
  axle.rotation.x = Math.PI / 2
  hub.add(axle)

  const bladeGroup = new THREE.Group()
  bladeGroup.position.z = 0.4
  hub.add(bladeGroup)
  for (let i = 0; i < 4; i++) {
    const arm = new THREE.Group()
    arm.rotation.z = i * Math.PI / 2
    const spar = box(0.28, 6.4, 0.16, wood)
    spar.position.y = 3.2
    arm.add(spar)
    for (let k = 0; k < 4; k++) {
      const slat = box(1.2, 0.85, 0.06, sailMat)
      slat.position.set(0.72, 2.0 + k * 1.25, 0)
      arm.add(slat)
      const slat2 = box(1.2, 0.85, 0.06, sailMat)
      slat2.position.set(-0.72, 2.0 + k * 1.25, 0)
      arm.add(slat2)
    }
    arm.traverse(o => { if (o.isMesh) o.castShadow = true })
    bladeGroup.add(arm)
  }
  const hubCap = new THREE.Mesh(new THREE.SphereGeometry(0.45, 10, 10), wood)
  hub.add(hubCap)

  root.add(group)
  return { group, bladeGroup, x, z, radius: 4.8 }
}

function makeSign(root, x, z, rot) {
  const h = heightAt(x, z)
  const postMat = new THREE.MeshStandardMaterial({ color: '#6f4a2d', roughness: 1 })
  const post1 = box(0.18, 2.7, 0.18, postMat)
  post1.position.set(x - 1.4, h + 1.35, z)
  const post2 = box(0.18, 2.7, 0.18, postMat)
  post2.position.set(x + 1.4, h + 1.35, z)
  root.add(post1, post2)

  const c = document.createElement('canvas')
  c.width = 512
  c.height = 224
  const ctx = c.getContext('2d')
  ctx.fillStyle = '#7d5230'
  ctx.fillRect(0, 0, 512, 224)
  ctx.fillStyle = '#8d5f38'
  for (let i = 0; i < 6; i++) ctx.fillRect(0, i * 38, 512, 2)
  ctx.strokeStyle = '#e8d3a8'
  ctx.lineWidth = 8
  ctx.strokeRect(12, 12, 488, 200)
  ctx.fillStyle = '#fff4d6'
  ctx.font = 'bold 74px Trebuchet MS, sans-serif'
  ctx.textAlign = 'center'
  ctx.fillText('LUSH VALLEY', 256, 102)
  ctx.font = 'bold 36px Trebuchet MS, sans-serif'
  ctx.fillStyle = '#ffe08a'
  ctx.fillText('BRIDGE  →', 256, 164)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 4
  const board = new THREE.Mesh(new THREE.PlaneGeometry(3.6, 1.58), new THREE.MeshStandardMaterial({ map: tex, roughness: 0.9, side: THREE.DoubleSide }))
  board.position.set(x, h + 2.25, z + 0.02)
  board.rotation.y = rot
  board.castShadow = true
  root.add(board)
  const back = box(3.8, 1.7, 0.09, postMat)
  back.position.set(x, h + 2.25, z - 0.03)
  back.rotation.y = rot
  root.add(back)
}

function makeCampfire(root, x, z) {
  const h = heightAt(x, z)
  const stoneMat = new THREE.MeshStandardMaterial({ color: '#8f8b7d', roughness: 1 })
  const logMat = new THREE.MeshStandardMaterial({ color: '#5e3f24', roughness: 1 })
  const group = new THREE.Group()
  group.position.set(x, h, z)
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2
    const stone = new THREE.Mesh(new THREE.DodecahedronGeometry(0.34, 0), stoneMat)
    stone.position.set(Math.cos(a) * 1.25, 0.15, Math.sin(a) * 1.25)
    stone.scale.set(1.2, 0.7, 1)
    stone.rotation.set(a, a * 2, 0)
    stone.castShadow = true
    group.add(stone)
  }
  for (let i = 0; i < 3; i++) {
    const log = box(0.28, 0.28, 1.8, logMat)
    log.position.y = 0.2
    log.rotation.y = (i / 3) * Math.PI
    log.rotation.x = 0.18
    log.castShadow = true
    group.add(log)
  }
  const flameMat = new THREE.MeshStandardMaterial({
    color: '#ff9a3d',
    emissive: new THREE.Color('#ff7b1e'),
    emissiveIntensity: 2.2,
    roughness: 0.6,
    transparent: true,
    opacity: 0.92,
  })
  const flame = new THREE.Mesh(new THREE.ConeGeometry(0.42, 1.1, 6), flameMat)
  flame.position.y = 0.8
  group.add(flame)
  const inner = new THREE.Mesh(new THREE.ConeGeometry(0.2, 0.65, 5), new THREE.MeshStandardMaterial({
    color: '#ffe08a',
    emissive: new THREE.Color('#ffd166'),
    emissiveIntensity: 3,
  }))
  inner.position.y = 0.62
  group.add(inner)
  const light = new THREE.PointLight(0xff9a45, 10, 15, 2)
  light.position.set(0, 1.3, 0)
  group.add(light)
  root.add(group)
  return { group, flame, inner, light }
}

function makeCoins(root) {
  const coinMat = new THREE.MeshStandardMaterial({
    color: 0xffc93c,
    metalness: 0.9,
    roughness: 0.22,
    emissive: new THREE.Color(0xffa500),
    emissiveIntensity: 0.55,
  })
  const rimMat = new THREE.MeshStandardMaterial({
    color: 0xffe28a,
    metalness: 0.95,
    roughness: 0.18,
    emissive: new THREE.Color(0xffb733),
    emissiveIntensity: 0.7,
  })
  const coinGeo = new THREE.CylinderGeometry(0.42, 0.42, 0.1, 24)
  const rimGeo = new THREE.TorusGeometry(0.42, 0.055, 8, 24)
  const starGeo = new THREE.BoxGeometry(0.3, 0.3, 0.12)

  const glowCanvas = document.createElement('canvas')
  glowCanvas.width = glowCanvas.height = 128
  const gctx = glowCanvas.getContext('2d')
  const grad = gctx.createRadialGradient(64, 64, 4, 64, 64, 64)
  grad.addColorStop(0, 'rgba(255,220,120,0.85)')
  grad.addColorStop(0.45, 'rgba(255,190,70,0.25)')
  grad.addColorStop(1, 'rgba(255,180,50,0)')
  gctx.fillStyle = grad
  gctx.fillRect(0, 0, 128, 128)
  const glowTex = new THREE.CanvasTexture(glowCanvas)
  glowTex.colorSpace = THREE.SRGBColorSpace

  const placements = [
    [14, 35], [4, 28], [-6, 22],
    [-6, 10], [-6, -6], [-6, -18],
    [-14, -28], [8, -34], [30, -44],
    [52, -55], [62, -48], [-58, 54],
  ]

  const coins = placements.map(([x, z], index) => {
    const group = new THREE.Group()
    const deck = bridgeDeckAt(x, z)
    const ground = deck === null ? heightAt(x, z) : deck
    const baseY = ground + 1.35
    group.position.set(x, baseY, z)

    const coin = new THREE.Mesh(coinGeo, coinMat)
    coin.rotation.x = Math.PI / 2
    coin.castShadow = true
    group.add(coin)
    const rim = new THREE.Mesh(rimGeo, rimMat)
    rim.rotation.x = Math.PI / 2
    group.add(rim)
    const star = new THREE.Mesh(starGeo, rimMat)
    star.rotation.x = Math.PI / 2
    star.scale.set(0.6, 0.6, 0.25)
    group.add(star)

    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      opacity: 0.8,
    }))
    glow.scale.setScalar(2.6)
    group.add(glow)

    group.userData = { index, baseY, collected: false }
    root.add(group)
    return { group, baseY, collected: false, phase: index * 1.37, x, z }
  })

  return coins
}

export function createProps(scene) {
  const rng = mulberry32(1337)
  const root = new THREE.Group()
  scene.add(root)

  makeSky(scene)
  makeClouds(scene, rng)

  const houses = []
  houses.push(makeHouse(root, rng, { x: 24, z: 41, rot: -0.42, wallColor: '#f2e2c0', roofColor: '#a8493a', lamp: true }))
  houses.push(makeHouse(root, rng, { x: -27, z: 40, rot: 0.5, wallColor: '#d8e6ea', roofColor: '#7a5a44' }))
  houses.push(makeHouse(root, rng, { x: 52, z: -52, rot: 2.2, wallColor: '#f3d9b1', roofColor: '#8f4a3f', scale: 0.95, lamp: true }))

  const windmill = makeWindmill(root, -58, 54)
  const campfire = makeCampfire(root, 16, 30)

  const colliders = houses.map(h => ({ x: h.x, z: h.z, r: h.radius }))
  colliders.push({ x: windmill.x, z: windmill.z, r: 4.6 })

  const blocked = (x, z, pad = 0) => colliders.some(c => Math.hypot(x - c.x, z - c.z) < c.r + pad)

  makePath(root, [[12, 42], [10, 36], [9, 31], [6, 27], [2, 25], [-3, 22], [-6, 20]], 1.5, new THREE.MeshStandardMaterial({ color: '#b58c5c', roughness: 1, vertexColors: true }))
  makePath(root, [[8, 33], [13, 36], [18, 39], [22, 40]], 1.2, new THREE.MeshStandardMaterial({ color: '#b58c5c', roughness: 1, vertexColors: true }))
  makePath(root, [[4, 29], [-6, 33], [-15, 36], [-23, 39]], 1.2, new THREE.MeshStandardMaterial({ color: '#b58c5c', roughness: 1, vertexColors: true }))
  makePath(root, [[-6, -21], [-12, -26], [-22, -29], [-33, -31]], 1.1, new THREE.MeshStandardMaterial({ color: '#b58c5c', roughness: 1, vertexColors: true }))
  makePath(root, [[-6, -21], [2, -28], [10, -33], [22, -38]], 1.1, new THREE.MeshStandardMaterial({ color: '#b58c5c', roughness: 1, vertexColors: true }))

  makeFence(root, rng, 16, 46, 32, 46)
  makeFence(root, rng, 32, 46, 32, 36)
  makeFence(root, rng, 17, 36, 17, 41)

  makeSign(root, 14, 33, 0.15)

  makeTrees(root, rng, blocked)
  makeBushes(root, rng, blocked)
  makeRocks(root, rng)
  makeGrass(root, rng, blocked)
  makeFlowers(root, rng, blocked)
  makeReeds(root, rng)
  makeBridge(root, rng)

  const coins = makeCoins(root)

  return {
    root,
    coins,
    colliders,
    bridgeDeckAt,
    update(time, dt) {
      windmill.bladeGroup.rotation.z = time * 0.45
      const flicker = 0.85 + Math.sin(time * 9.3) * 0.08 + Math.sin(time * 17.1) * 0.05
      campfire.light.intensity = 9 * flicker
      campfire.flame.scale.set(1, flicker, 1)
      campfire.inner.scale.set(1, 0.85 + flicker * 0.2, 1)
      campfire.flame.rotation.y = time * 0.7
      for (const coin of coins) {
        if (coin.collected) continue
        coin.group.position.y = coin.baseY + Math.sin(time * 1.8 + coin.phase) * 0.16
        coin.group.rotation.y = time * 1.9 + coin.phase
      }
    },
  }
}

import * as THREE from 'three'
import { heightAt, WATER_LEVEL } from './terrain.js'

const clamp = THREE.MathUtils.clamp

function makeFaceTexture() {
  const c = document.createElement('canvas')
  c.width = c.height = 256
  const ctx = c.getContext('2d')
  ctx.fillStyle = '#f3c53f'
  ctx.fillRect(0, 0, 256, 256)

  // Classic blocky smile.
  ctx.fillStyle = '#2b2117'
  ctx.beginPath()
  ctx.ellipse(88, 112, 13, 18, 0, 0, Math.PI * 2)
  ctx.fill()
  ctx.beginPath()
  ctx.ellipse(168, 112, 13, 18, 0, 0, Math.PI * 2)
  ctx.fill()

  ctx.strokeStyle = '#2b2117'
  ctx.lineWidth = 12
  ctx.lineCap = 'round'
  ctx.beginPath()
  ctx.arc(128, 150, 44, 0.18 * Math.PI, 0.82 * Math.PI)
  ctx.stroke()

  // Cheek blush.
  ctx.fillStyle = 'rgba(235,120,85,0.28)'
  ctx.beginPath()
  ctx.ellipse(58, 158, 18, 11, 0, 0, Math.PI * 2)
  ctx.fill()
  ctx.beginPath()
  ctx.ellipse(198, 158, 18, 11, 0, 0, Math.PI * 2)
  ctx.fill()

  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 4
  return tex
}

function makeNameTag(text) {
  const c = document.createElement('canvas')
  c.width = 512
  c.height = 128
  const ctx = c.getContext('2d')
  ctx.font = 'bold 62px Trebuchet MS, sans-serif'
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  ctx.lineWidth = 12
  ctx.strokeStyle = 'rgba(20,38,24,0.75)'
  ctx.strokeText(text, 256, 68)
  ctx.fillStyle = '#ffffff'
  ctx.fillText(text, 256, 68)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: tex,
    transparent: true,
    depthTest: true,
    depthWrite: false,
  }))
  sprite.scale.set(2.8, 0.7, 1)
  return sprite
}

function buildAvatar() {
  const group = new THREE.Group()
  const skin = new THREE.MeshStandardMaterial({ color: '#f3c53f', roughness: 0.75 })
  const shirt = new THREE.MeshStandardMaterial({ color: '#35a85a', roughness: 0.8 })
  const shirtDark = new THREE.MeshStandardMaterial({ color: '#2a8a49', roughness: 0.85 })
  const pants = new THREE.MeshStandardMaterial({ color: '#3c4a78', roughness: 0.85 })
  const shoe = new THREE.MeshStandardMaterial({ color: '#34343f', roughness: 0.7 })
  const white = new THREE.MeshStandardMaterial({ color: '#f6f3e6', roughness: 0.7 })

  const boxMesh = (w, h, d, mat) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat)
    m.castShadow = true
    m.receiveShadow = true
    return m
  }

  // Torso.
  const torso = boxMesh(1.5, 1.55, 0.78, shirt)
  torso.position.y = 2.29
  group.add(torso)
  const belt = boxMesh(1.52, 0.18, 0.8, shirtDark)
  belt.position.y = 1.56
  group.add(belt)
  const badge = boxMesh(0.34, 0.34, 0.03, white)
  badge.position.set(0, 2.55, 0.4)
  group.add(badge)
  const badgeDot = boxMesh(0.14, 0.14, 0.02, shirt)
  badgeDot.position.set(0, 2.55, 0.42)
  group.add(badgeDot)

  // Head.
  const faceMat = new THREE.MeshStandardMaterial({ map: makeFaceTexture(), roughness: 0.72 })
  const headGeo = new THREE.BoxGeometry(1.08, 1.04, 1.04)
  const head = new THREE.Mesh(headGeo, [skin, skin, skin, skin, faceMat, skin])
  head.position.y = 3.58
  head.castShadow = true
  head.receiveShadow = true
  group.add(head)

  // Arms with shoulder pivots.
  const armL = new THREE.Group()
  armL.position.set(-0.97, 2.95, 0)
  const armLMesh = boxMesh(0.42, 1.5, 0.44, skin)
  armLMesh.position.y = -0.75
  armL.add(armLMesh)
  const sleeveL = boxMesh(0.46, 0.34, 0.48, shirtDark)
  sleeveL.position.y = -0.12
  armL.add(sleeveL)
  group.add(armL)

  const armR = armL.clone()
  armR.position.x = 0.97
  group.add(armR)

  // Legs with hip pivots.
  const legL = new THREE.Group()
  legL.position.set(-0.38, 1.5, 0)
  const legLMesh = boxMesh(0.52, 1.4, 0.56, pants)
  legLMesh.position.y = -0.72
  legL.add(legLMesh)
  const shoeL = boxMesh(0.56, 0.22, 0.68, shoe)
  shoeL.position.set(0, -1.42, 0.04)
  legL.add(shoeL)
  group.add(legL)

  const legR = legL.clone()
  legR.position.x = 0.38
  group.add(legR)

  const tag = makeNameTag('Explorer')
  tag.position.y = 4.75
  group.add(tag)

  group.traverse(o => {
    if (o.isMesh) {
      o.castShadow = true
      o.receiveShadow = true
    }
  })

  return { group, armL, armR, legL, legR, head, torso, tag }
}

export class Player {
  constructor({ scene, camera, canvas, colliders, bridgeDeckAt }) {
    this.camera = camera
    this.canvas = canvas
    this.colliders = colliders
    this.bridgeDeckAt = bridgeDeckAt
    this.enabled = false

    this.spawn = new THREE.Vector3(11, heightAt(11, 47), 47)
    this.position = this.spawn.clone()
    this.velocity = new THREE.Vector3()
    this.grounded = true
    this.keys = new Set()
    this.touchMove = new THREE.Vector2()
    this.jumpQueued = false
    this.sprinting = false
    this.facing = Math.PI
    this.walkPhase = 0
    this.moving = false

    this.yaw = 0
    this.pitch = 0.24
    this.distance = 10.5
    this.cameraTarget = new THREE.Vector3()
    this.cameraInitialized = false

    const avatar = buildAvatar()
    this.avatar = avatar
    this.model = avatar.group
    this.model.position.copy(this.position)
    this.model.rotation.y = this.facing
    scene.add(this.model)

    this.onJump = null
    this.onStep = null
    this.stepTimer = 0

    this.raycaster = new THREE.Raycaster()
    this.bindEvents()
  }

  bindEvents() {
    window.addEventListener('keydown', (e) => {
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault()
      this.keys.add(e.code)
      if (e.code === 'Space' && this.enabled && !e.repeat) this.jumpQueued = true
      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') this.sprinting = true
    })
    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code)
      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') this.sprinting = false
    })
    window.addEventListener('blur', () => {
      this.keys.clear()
      this.sprinting = false
    })

    let dragId = null
    let lastX = 0
    let lastY = 0
    const canvas = this.canvas
    canvas.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return
      dragId = e.pointerId
      lastX = e.clientX
      lastY = e.clientY
      canvas.setPointerCapture(e.pointerId)
      canvas.classList.add('dragging')
    })
    canvas.addEventListener('pointermove', (e) => {
      if (dragId !== e.pointerId) return
      const dx = e.clientX - lastX
      const dy = e.clientY - lastY
      lastX = e.clientX
      lastY = e.clientY
      this.yaw -= dx * 0.0045
      this.pitch = clamp(this.pitch + dy * 0.0032, -0.12, 1.0)
    })
    const endDrag = (e) => {
      if (dragId !== e.pointerId) return
      dragId = null
      canvas.classList.remove('dragging')
      try { canvas.releasePointerCapture(e.pointerId) } catch {}
    }
    canvas.addEventListener('pointerup', endDrag)
    canvas.addEventListener('pointercancel', endDrag)
    canvas.addEventListener('wheel', (e) => {
      if (!this.enabled) return
      e.preventDefault()
      this.distance = clamp(this.distance + e.deltaY * 0.012, 4.5, 18)
    }, { passive: false })
  }

  setTouchMove(x, y) {
    this.touchMove.set(x, y)
  }

  requestJump() {
    if (this.enabled) this.jumpQueued = true
  }

  groundAt(x, z) {
    const terrain = heightAt(x, z)
    const deck = this.bridgeDeckAt(x, z)
    return deck === null ? terrain : Math.max(terrain, deck)
  }

  update(dt, time) {
    const keys = this.keys
    const started = this.enabled

    let forwardInput = 0
    let strafeInput = 0
    if (started) {
      if (keys.has('KeyW') || keys.has('ArrowUp')) forwardInput += 1
      if (keys.has('KeyS') || keys.has('ArrowDown')) forwardInput -= 1
      if (keys.has('KeyD') || keys.has('ArrowRight')) strafeInput += 1
      if (keys.has('KeyA') || keys.has('ArrowLeft')) strafeInput -= 1
      forwardInput = clamp(forwardInput + this.touchMove.y, -1, 1)
      strafeInput = clamp(strafeInput + this.touchMove.x, -1, 1)
    }

    const forward = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw))
    const right = new THREE.Vector3(-forward.z, 0, forward.x)
    const wish = new THREE.Vector3()
      .addScaledVector(forward, forwardInput)
      .addScaledVector(right, strafeInput)
    if (wish.lengthSq() > 1) wish.normalize()

    const groundBefore = this.groundAt(this.position.x, this.position.z)
    const wading = groundBefore < WATER_LEVEL + 0.25
    const baseSpeed = this.sprinting ? 10.2 : 6.4
    const speed = baseSpeed * (wading ? 0.62 : 1)
    const desiredX = wish.x * speed
    const desiredZ = wish.z * speed
    const accel = this.grounded ? 13 : 3.6
    const blend = 1 - Math.exp(-accel * dt)
    this.velocity.x += (desiredX - this.velocity.x) * blend
    this.velocity.z += (desiredZ - this.velocity.z) * blend

    if (this.jumpQueued && this.grounded) {
      this.velocity.y = 12.2
      this.grounded = false
      this.onJump?.()
    }
    this.jumpQueued = false

    const nx = this.position.x + this.velocity.x * dt
    const nz = this.position.z + this.velocity.z * dt

    const passable = (x, z) => {
      if (Math.abs(x) > 100 || Math.abs(z) > 100) return false
      const deck = this.bridgeDeckAt(x, z)
      if (deck !== null) return true
      return heightAt(x, z) > WATER_LEVEL - 0.7
    }

    if (passable(nx, nz)) {
      this.position.x = nx
      this.position.z = nz
    } else if (passable(nx, this.position.z)) {
      this.position.x = nx
      this.velocity.z *= 0.2
    } else if (passable(this.position.x, nz)) {
      this.position.z = nz
      this.velocity.x *= 0.2
    } else {
      this.velocity.x *= 0.1
      this.velocity.z *= 0.1
    }

    for (const collider of this.colliders) {
      const dx = this.position.x - collider.x
      const dz = this.position.z - collider.z
      const dist = Math.hypot(dx, dz)
      if (dist < collider.r && dist > 0.0001) {
        const push = collider.r - dist
        this.position.x += (dx / dist) * push
        this.position.z += (dz / dist) * push
      }
    }

    const ground = this.groundAt(this.position.x, this.position.z)
    this.velocity.y -= 34 * dt
    this.position.y += this.velocity.y * dt
    if (this.position.y <= ground) {
      this.position.y = ground
      this.velocity.y = 0
      this.grounded = true
    } else {
      this.grounded = false
    }

    const horizontalSpeed = Math.hypot(this.velocity.x, this.velocity.z)
    this.moving = horizontalSpeed > 0.6
    if (this.moving) {
      const targetFacing = Math.atan2(this.velocity.x, this.velocity.z)
      let diff = targetFacing - this.facing
      while (diff > Math.PI) diff -= Math.PI * 2
      while (diff < -Math.PI) diff += Math.PI * 2
      this.facing += diff * (1 - Math.exp(-14 * dt))
      this.walkPhase += dt * (6 + horizontalSpeed * 0.55)
      this.stepTimer -= dt
      if (this.grounded && this.stepTimer <= 0) {
        this.stepTimer = this.sprinting ? 0.26 : 0.4
        this.onStep?.()
      }
    } else {
      this.walkPhase += dt * 1.2
      this.stepTimer = 0
    }

    const { armL, armR, legL, legR, head, tag } = this.avatar
    if (!this.grounded) {
      armL.rotation.x = -0.9
      armR.rotation.x = -0.9
      legL.rotation.x = 0.35
      legR.rotation.x = -0.25
    } else if (this.moving) {
      const swing = Math.sin(this.walkPhase) * clamp(horizontalSpeed / 7, 0.4, 1.25)
      legL.rotation.x = swing * 0.75
      legR.rotation.x = -swing * 0.75
      armL.rotation.x = -swing * 0.65
      armR.rotation.x = swing * 0.65
    } else {
      const idle = Math.sin(time * 1.6) * 0.05
      legL.rotation.x += (0 - legL.rotation.x) * 0.12
      legR.rotation.x += (0 - legR.rotation.x) * 0.12
      armL.rotation.x += (idle - armL.rotation.x) * 0.1
      armR.rotation.x += (-idle - armR.rotation.x) * 0.1
    }
    if (head) head.rotation.z = Math.sin(time * 1.1) * 0.015
    if (tag) tag.position.y = 4.75 + Math.sin(time * 2.2) * 0.03

    this.model.position.copy(this.position)
    this.model.rotation.y = this.facing

    // Camera: slow cinematic orbit before play, free orbit after.
    if (!started) {
      this.yaw += dt * 0.055
      this.pitch = 0.22
    }
    const target = new THREE.Vector3(
      this.position.x,
      this.position.y + 2.65,
      this.position.z,
    )
    if (!this.cameraInitialized) {
      this.cameraTarget.copy(target)
      this.cameraInitialized = true
    } else {
      this.cameraTarget.lerp(target, 1 - Math.exp(-12 * dt))
    }

    const cosPitch = Math.cos(this.pitch)
    const offset = new THREE.Vector3(
      Math.sin(this.yaw) * cosPitch,
      Math.sin(this.pitch),
      Math.cos(this.yaw) * cosPitch,
    ).multiplyScalar(this.distance)

    const desired = this.cameraTarget.clone().add(offset)
    const minY = heightAt(desired.x, desired.z) + 1.15
    if (desired.y < minY) desired.y = minY
    if (!this.cameraInitialized) this.camera.position.copy(desired)
    else this.camera.position.lerp(desired, 1 - Math.exp(-9 * dt))
    this.camera.lookAt(this.cameraTarget)
  }
}

export class AudioKit {
  constructor() {
    this.ctx = null
    this.master = null
    this.muted = false
    this.birdTimer = null
  }

  start() {
    if (this.ctx) {
      this.ctx.resume?.()
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    this.ctx = new Ctx()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.muted ? 0 : 0.55
    this.master.connect(this.ctx.destination)
    this.startWind()
    this.scheduleBird()
  }

  setMuted(muted) {
    this.muted = muted
    if (this.master) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.55, this.ctx.currentTime, 0.05)
    }
  }

  startWind() {
    const ctx = this.ctx
    const seconds = 3
    const buffer = ctx.createBuffer(1, ctx.sampleRate * seconds, ctx.sampleRate)
    const data = buffer.getChannelData(0)
    let last = 0
    for (let i = 0; i < data.length; i++) {
      const white = Math.random() * 2 - 1
      last = last * 0.985 + white * 0.015
      data[i] = last * 3.2
    }
    const source = ctx.createBufferSource()
    source.buffer = buffer
    source.loop = true
    const filter = ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 420
    const gain = ctx.createGain()
    gain.gain.value = 0.09
    source.connect(filter).connect(gain).connect(this.master)
    source.start()
  }

  scheduleBird() {
    if (this.birdTimer) clearTimeout(this.birdTimer)
    const delay = 3800 + Math.random() * 6500
    this.birdTimer = setTimeout(() => {
      if (!this.muted) this.chirp()
      this.scheduleBird()
    }, delay)
  }

  chirp() {
    if (!this.ctx) return
    const ctx = this.ctx
    const now = ctx.currentTime
    const notes = 2 + Math.floor(Math.random() * 3)
    for (let i = 0; i < notes; i++) {
      const t = now + i * 0.11
      const osc = ctx.createOscillator()
      const gain = ctx.createGain()
      osc.type = 'sine'
      const base = 1900 + Math.random() * 900
      osc.frequency.setValueAtTime(base, t)
      osc.frequency.exponentialRampToValueAtTime(base * (1.25 + Math.random() * 0.3), t + 0.06)
      gain.gain.setValueAtTime(0, t)
      gain.gain.linearRampToValueAtTime(0.045, t + 0.015)
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.1)
      osc.connect(gain).connect(this.master)
      osc.start(t)
      osc.stop(t + 0.12)
    }
  }

  tone(freq, start, duration, type = 'triangle', volume = 0.12) {
    if (!this.ctx) return
    const ctx = this.ctx
    const t = ctx.currentTime + start
    const osc = ctx.createOscillator()
    const gain = ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    gain.gain.setValueAtTime(0, t)
    gain.gain.linearRampToValueAtTime(volume, t + 0.015)
    gain.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    osc.connect(gain).connect(this.master)
    osc.start(t)
    osc.stop(t + duration + 0.05)
  }

  coin(index = 0) {
    const scale = [523.25, 587.33, 659.25, 783.99, 880]
    const base = scale[index % scale.length]
    this.tone(base * 2, 0, 0.22, 'sine', 0.11)
    this.tone(base * 3, 0.05, 0.3, 'triangle', 0.07)
    this.tone(base * 4, 0.11, 0.28, 'sine', 0.04)
  }

  jump() {
    if (!this.ctx) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const osc = ctx.createOscillator()
    const gain = ctx.createGain()
    osc.type = 'triangle'
    osc.frequency.setValueAtTime(240, t)
    osc.frequency.exponentialRampToValueAtTime(430, t + 0.14)
    gain.gain.setValueAtTime(0, t)
    gain.gain.linearRampToValueAtTime(0.05, t + 0.01)
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.18)
    osc.connect(gain).connect(this.master)
    osc.start(t)
    osc.stop(t + 0.2)
  }

  step() {
    this.tone(120 + Math.random() * 30, 0, 0.07, 'sine', 0.025)
  }

  complete() {
    const melody = [523.25, 659.25, 783.99, 1046.5, 1318.5]
    melody.forEach((f, i) => {
      this.tone(f, i * 0.11, 0.55, 'triangle', 0.1)
      this.tone(f * 2, i * 0.11, 0.4, 'sine', 0.035)
    })
  }
}

