const touchUi = document.getElementById('touch')

const totalCoins = props.coins.length
coinTotalEl.textContent = String(totalCoins)
let collected = 0
let running = false
let toastTimer = 0

const messages = ['Shiny!', 'Ka-ching!', 'Found one!', 'Nice find!', 'Cha-ching!']

function showToast(text) {
  toast.textContent = text
  toast.classList.add('show')
  clearTimeout(toastTimer)
  toastTimer = setTimeout(() => toast.classList.remove('show'), 1600)
}

function refreshHud() {
  coinCountEl.textContent = String(collected)
  coinCountEl.classList.remove('pop')
  void coinCountEl.offsetWidth
  coinCountEl.classList.add('pop')
}

function collectCoin(coin) {
  if (coin.collected) return
  coin.collected = true
  coin.group.visible = false
  collected++
  refreshHud()
  audio.coin(collected)
  sparkles.spawn(coin.group.position, 30, 1.1, 5)
  showToast(`${messages[collected % messages.length]}  ${collected}/${totalCoins}`)

  if (collected === totalCoins) {
    setTimeout(() => {
      complete.classList.add('show')
      audio.complete()
      sparkles.spawn(new THREE.Vector3(player.position.x, player.position.y + 4, player.position.z), 80, 3.4, 7)
    }, 450)
  }
}

function startGame() {
  if (running) return
  running = true
  player.enabled = true
  title.classList.add('hidden')
  hud.classList.add('visible')
  audio.start()
  setTimeout(() => hint.classList.add('dim'), 12000)
  document.body.classList.add('playing')
}

playButton.addEventListener('click', startGame)
window.addEventListener('keydown', (e) => {
  if (!running && (e.code === 'Enter' || e.code === 'Space')) startGame()
})

document.getElementById('resume').addEventListener('click', () => {
  complete.classList.remove('show')
})

let muted = false
soundButton.addEventListener('click', () => {
  muted = !muted
  audio.setMuted(muted)
  soundButton.textContent = muted ? '🔇' : '🔊'
  soundButton.setAttribute('aria-label', muted ? 'Unmute sound' : 'Mute sound')
  soundButton.classList.toggle('off', muted)
})

const isTouch = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window
if (isTouch) {
  document.body.classList.add('touch')
  hint.innerHTML = '<b>Drag</b> to look · <b>Stick</b> to move · <b>Jump</b> to hop'
}

// Touch joystick.
const stick = document.getElementById('stick')
const knob = document.getElementById('knob')
const jumpButton = document.getElementById('jump')
let stickId = null
let stickCenter = { x: 0, y: 0 }

function updateStick(e) {
  const dx = e.clientX - stickCenter.x
  const dy = e.clientY - stickCenter.y
  const max = 46
  const dist = Math.hypot(dx, dy)
  const clamped = Math.min(dist, max)
  const angle = Math.atan2(dy, dx)
  const kx = Math.cos(angle) * clamped
  const ky = Math.sin(angle) * clamped
  knob.style.transform = `translate(${kx}px, ${ky}px)`
  player.setTouchMove(
    (kx / max),
    (-ky / max),
  )
}

stick.addEventListener('pointerdown', (e) => {
  if (!running) return
  e.preventDefault()
  stickId = e.pointerId
  const rect = stick.getBoundingClientRect()
  stickCenter = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 }
  stick.setPointerCapture(e.pointerId)
  stick.classList.add('active')
  updateStick(e)
})
stick.addEventListener('pointermove', (e) => {
  if (e.pointerId !== stickId) return
  e.preventDefault()
  updateStick(e)
})
const releaseStick = (e) => {
  if (e.pointerId !== stickId) return
  stickId = null
  knob.style.transform = 'translate(0,0)'
  player.setTouchMove(0, 0)
  stick.classList.remove('active')
}
stick.addEventListener('pointerup', releaseStick)
stick.addEventListener('pointercancel', releaseStick)

jumpButton.addEventListener('pointerdown', (e) => {
  e.preventDefault()
  player.requestJump()
})

// ---------------------------------------------------------------- main loop

const clock = new THREE.Clock()
let elapsed = 0

function animate() {
  const dt = Math.min(clock.getDelta(), 0.05)
  elapsed += dt

  player.update(dt, elapsed)
  world.update(elapsed)
  props.update(elapsed, dt)
  sparkles.update(dt)
  pollen.update(elapsed)

  if (running) {
    for (const coin of props.coins) {
      if (coin.collected) continue
      const dx = player.position.x - coin.x
      const dz = player.position.z - coin.z
      const dy = (player.position.y + 2.1) - coin.group.position.y
      if (Math.abs(dx) < 2.1 && Math.abs(dz) < 2.1 && Math.abs(dy) < 2.9) {
        collectCoin(coin)
      }
    }
  }

  // Keep the shadow frustum around the player so distant hills stay cheap.
  sun.position.set(player.position.x + sunDir.x * 110, sunDir.y * 110, player.position.z + sunDir.z * 110)
  sun.target.position.set(player.position.x, 0, player.position.z)
  sun.target.updateMatrixWorld()

  renderer.render(scene, camera)
  requestAnimationFrame(animate)
}

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight
  camera.updateProjectionMatrix()
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2))
  renderer.setSize(window.innerWidth, window.innerHeight)
})

renderer.compile(scene, camera)
requestAnimationFrame(animate)

:root {
  --cream: #f6f0d8;
  --lime: #a8e35d;
  --lime-deep: #7bc946;
  --pine: #17361f;
  --ink: #182a1d;
  --panel: rgba(12, 28, 17, 0.55);
  --shadow: 0 22px 60px rgba(6, 18, 9, 0.45);
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #0d1a11;
  color: var(--cream);
  font-family: ui-rounded, "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

#game {
  position: fixed;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
  outline: none;
}

#game.dragging {
  cursor: grabbing;
}

.vignette {
  position: fixed;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    radial-gradient(circle at 50% 45%, transparent 52%, rgba(7, 20, 11, 0.38) 100%),
    linear-gradient(180deg, rgba(7, 18, 10, 0.25) 0%, transparent 18%, transparent 78%, rgba(7, 18, 10, 0.32) 100%);
}

/* ------------------------------------------------------------------ title */

.screen {
  position: fixed;
  inset: 0;
  z-index: 10;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: clamp(18px, 3vw, 38px) clamp(20px, 5vw, 72px) clamp(16px, 3vw, 32px);
  background:
    radial-gradient(ellipse at 18% 68%, rgba(8, 26, 13, 0.78) 0%, rgba(8, 26, 13, 0.42) 34%, transparent 64%),
    linear-gradient(180deg, rgba(8, 20, 11, 0.48) 0%, transparent 26%, transparent 62%, rgba(8, 20, 11, 0.62) 100%);
  transition: opacity 0.7s ease, visibility 0.7s;
}

.screen.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  font-size: 13px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(246, 240, 216, 0.72);
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: linear-gradient(150deg, var(--lime), #5faa39);
  color: #14331b;
  font-weight: 900;
  font-size: 14px;
  letter-spacing: 0.02em;
  box-shadow: inset 0 -3px 0 rgba(10, 40, 16, 0.22), 0 6px 18px rgba(0, 0, 0, 0.25);
}

.brand-name {
  font-weight: 800;
  color: rgba(246, 240, 216, 0.9);
}

.topbar-note {
  padding: 9px 16px;
  border: 1px solid rgba(246, 240, 216, 0.18);
  border-radius: 999px;
  background: rgba(10, 26, 15, 0.28);
  backdrop-filter: blur(6px);
}

.hero {
  max-width: 42rem;
  margin-top: auto;
  margin-bottom: clamp(6px, 3vh, 42px);
  animation: rise 0.9s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(18px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 16px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--lime);
}

.eyebrow .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 14px var(--lime);
}

h1 {
  margin: 0;
  font-size: clamp(64px, 10.5vw, 146px);
  line-height: 0.82;
  letter-spacing: -0.05em;
  font-weight: 900;
  text-transform: uppercase;
  text-shadow: 0 18px 50px rgba(3, 14, 6, 0.55);
}

h1 .accent {
  display: block;
  background: linear-gradient(100deg, #d6f79a 0%, #9be257 45%, #64bd3c 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 10px 28px rgba(20, 60, 24, 0.45));
}

.lede {
  max-width: 31rem;
  margin: 22px 0 0;
  font-size: clamp(15px, 1.5vw, 18px);
  line-height: 1.55;
  color: rgba(244, 240, 218, 0.82);
  text-shadow: 0 2px 16px rgba(1, 10, 4, 0.55);
}

.actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 26px;
  margin-top: 34px;
}

.play {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  padding: 17px 42px 17px 34px;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(180deg, #c2f57f 0%, #8ada4b 55%, #6fc53c 100%);
  color: #14351c;
  font-family: inherit;
  font-size: 20px;
  font-weight: 900;
  letter-spacing: 0.01em;
  cursor: pointer;
  box-shadow:
    0 16px 34px rgba(4, 18, 8, 0.45),
    0 0 0 6px rgba(168, 227, 93, 0.12),
    inset 0 -4px 0 rgba(31, 88, 30, 0.28);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.play:hover,
.play:focus-visible {
  transform: translateY(-2px) scale(1.015);
  box-shadow:
    0 22px 44px rgba(4, 18, 8, 0.5),
    0 0 0 8px rgba(168, 227, 93, 0.16),
    inset 0 -4px 0 rgba(31, 88, 30, 0.28);
  outline: none;
}

.play:active {
  transform: translateY(1px) scale(0.99);
}

.play-icon {
  width: 0;
  height: 0;
  border-top: 8px solid transparent;
  border-bottom: 8px solid transparent;
  border-left: 13px solid #1a4022;
  filter: drop-shadow(0 1px 0 rgba(255, 255, 255, 0.25));
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  font-size: 12.5px;
  color: rgba(244, 240, 218, 0.72);
}

.ctrl {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

kbd {
  display: inline-grid;
  place-items: center;
  min-width: 24px;
  height: 24px;
  padding: 0 6px;
  border-radius: 7px;
  border: 1px solid rgba(246, 240, 216, 0.24);
  border-bottom-width: 2px;
  background: rgba(246, 240, 216, 0.1);
  color: rgba(249, 246, 226, 0.92);
  font-family: inherit;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12);
}

.title-foot {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(241, 236, 211, 0.5);
}

.title-foot .sep {
  opacity: 0.5;
}

/* -------------------------------------------------------------------- hud */

#hud {
  position: fixed;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-6px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}

#hud.visible {
  opacity: 1;
  transform: translateY(0);
}

.hud-top {
  position: absolute;
  top: calc(18px + env(safe-area-inset-top));
  left: calc(18px + env(safe-area-inset-left));
  right: calc(18px + env(safe-area-inset-right));
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 9px 12px;
  border-radius: 18px;
  background: rgba(255, 253, 245, 0.93);
  color: var(--ink);
  box-shadow: 0 14px 34px rgba(4, 16, 8, 0.35), inset 0 0 0 1px rgba(255, 255, 255, 0.6);
  backdrop-filter: blur(8px);
}

.who {
  display: flex;
  align-items: center;
  gap: 10px;
}

.avatar-chip {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: linear-gradient(160deg, #47b264, #2c7b45);
  color: #f7f3dd;
  font-weight: 900;
  font-size: 17px;
  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.16);
}

.who-text {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.who-text b {
  font-size: 14px;
  letter-spacing: 0.01em;
}

.who-text small {
  margin-top: 3px;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #72816f;
}

.coins {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 8px 14px;
  border-radius: 999px;
  background: #f4efdd;
  font-size: 17px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  color: #3e4526;
  box-shadow: inset 0 1px 2px rgba(80, 70, 30, 0.14);
}

.coins i {
  font-style: normal;
  opacity: 0.35;
}

.coin-dot {
  width: 17px;
  height: 17px;
  margin-right: 4px;
  border-radius: 50%;
  background: radial-gradient(circle at 34% 30%, #fff3b0, #ffc93c 55%, #d58f14);
  box-shadow: 0 0 0 2px rgba(213, 143, 20, 0.32), inset 0 0 0 2px rgba(255, 236, 160, 0.6);
}

#coinCount.pop {
  animation: coinpop 0.45s cubic-bezier(0.2, 1.6, 0.4, 1);
}

@keyframes coinpop {
  0% {
    transform: scale(1);
    color: #3e4526;
  }
  40% {
    transform: scale(1.45);
    color: #c98a12;
  }
  100% {
    transform: scale(1);
    color: #3e4526;
  }
}

#sound {
  pointer-events: auto;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 253, 245, 0.9);
  color: #1d3324;
  font-size: 18px;
  cursor: pointer;
  box-shadow: 0 10px 24px rgba(4, 16, 8, 0.32);
  transition: transform 0.15s ease, opacity 0.15s ease;
}

#sound:hover {
  transform: scale(1.06);
}

#sound.off {
  opacity: 0.7;
}

#hint {
  position: absolute;
  left: 50%;
  bottom: calc(20px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 18px;
  max-width: calc(100vw - 32px);
  padding: 11px 20px;
  border-radius: 999px;
  background: rgba(10, 26, 15, 0.55);
  border: 1px solid rgba(246, 240, 216, 0.14);
  backdrop-filter: blur(10px);
  font-size: 12px;
  color: rgba(246, 241, 219, 0.82);
  transition: opacity 0.6s ease;
}

#hint.dim {
  opacity: 0.45;
}

#hint span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

#hint kbd {
  height: 21px;
  min-width: 21px;
  border-color: rgba(246, 240, 216, 0.2);
  background: rgba(255, 255, 255, 0.08);
  font-size: 10px;
}

#toast {
  position: absolute;
  left: 50%;
  bottom: calc(84px + env(safe-area-inset-bottom));
  transform: translate(-50%, 10px);
  padding: 11px 22px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(255, 249, 222, 0.97), rgba(245, 232, 187, 0.97));
  color: #4a3a12;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.02em;
  opacity: 0;
  pointer-events: none;
  box-shadow: 0 14px 30px rgba(3, 14, 6, 0.4);
  transition: opacity 0.25s ease, transform 0.25s ease;
  white-space: nowrap;
}

#toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

#complete {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 24px;
  background: radial-gradient(circle at 50% 45%, rgba(12, 34, 18, 0.2), rgba(6, 18, 10, 0.62));
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.45s ease, visibility 0.45s;
  pointer-events: none;
}

#complete.show {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.complete-card {
  width: min(440px, 100%);
  padding: 38px 34px 34px;
  border-radius: 26px;
  text-align: center;
  background: linear-gradient(170deg, rgba(255, 253, 244, 0.98), rgba(240, 246, 222, 0.98));
  color: var(--ink);
  box-shadow: var(--shadow), inset 0 0 0 1px rgba(255, 255, 255, 0.7);
  transform: translateY(12px) scale(0.97);
  transition: transform 0.45s cubic-bezier(0.2, 0.9, 0.3, 1.2);
}

#complete.show .complete-card {
  transform: translateY(0) scale(1);
}

.complete-kicker {
  display: inline-block;
  padding: 7px 14px;
  border-radius: 999px;
  background: #e5f6c8;
  color: #3c6b26;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.complete-card h2 {
  margin: 16px 0 8px;
  font-size: 34px;
  letter-spacing: -0.03em;
  color: #1c4324;
}

.complete-card p {
  margin: 0 0 24px;
  font-size: 14.5px;
  line-height: 1.55;
  color: #5f6c58;
}

.complete-card button {
  padding: 13px 28px;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(180deg, #b6ec73, #83d148);
  color: #18371f;
  font-family: inherit;
  font-size: 15px;
  font-weight: 900;
  cursor: pointer;
  box-shadow: 0 10px 22px rgba(37, 90, 30, 0.28);
}

/* ------------------------------------------------------------------ touch */

#touch {
  display: none;
}

body.touch #touch {
  display: block;
}

#stick {
  position: absolute;
  left: calc(22px + env(safe-area-inset-left));
  bottom: calc(26px + env(safe-area-inset-bottom));
  width: 118px;
  height: 118px;
  border-radius: 50%;
  border: 1px solid rgba(246, 240, 216, 0.28);
  background: rgba(10, 28, 16, 0.32);
  backdrop-filter: blur(6px);
  pointer-events: auto;
  touch-action: none;
}

#knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 52px;
  height: 52px;
  margin: -26px 0 0 -26px;
  border-radius: 50%;
  background: rgba(246, 247, 225, 0.9);
  box-shadow: 0 8px 18px rgba(3, 14, 6, 0.4);
  transition: transform 0.05s linear;
}

#stick.active {
  background: rgba(20, 48, 26, 0.45);
}

#jump {
  position: absolute;
  right: calc(26px + env(safe-area-inset-right));
  bottom: calc(36px + env(safe-area-inset-bottom));
  width: 82px;
  height: 82px;
  border: 0;
  border-radius: 50%;
  background: linear-gradient(180deg, #c2f57f, #82d247);
  color: #17361f;
  font-family: inherit;
  font-size: 14px;
  font-weight: 900;
  letter-spacing: 0.04em;
  pointer-events: auto;
  touch-action: none;
  box-shadow: 0 12px 26px rgba(3, 14, 6, 0.42), inset 0 -4px 0 rgba(31, 88, 30, 0.25);
}

body.touch #hint {
  display: none;
}

body.touch #toast {
  bottom: calc(160px + env(safe-area-inset-bottom));
}

/* --------------------------------------------------------------- responsive */

@media (max-width: 760px) {
  .screen {
    background:
      radial-gradient(ellipse at 50% 78%, rgba(8, 26, 13, 0.72) 0%, rgba(8, 26, 13, 0.4) 45%, transparent 75%),
      linear-gradient(180deg, rgba(8, 20, 11, 0.5) 0%, transparent 24%, transparent 50%, rgba(8, 20, 11, 0.72) 100%);
  }

  .topbar-note,
  .title-foot {
    display: none;
  }

  .hero {
    margin-top: auto;
    margin-bottom: 7vh;
  }

  h1 {
    font-size: clamp(56px, 17vw, 96px);
  }

  .lede {
    max-width: 26rem;
    font-size: 14.5px;
    margin-top: 16px;
  }

  .actions {
    gap: 18px;
    margin-top: 24px;
  }

  .play {
    padding: 15px 32px 15px 26px;
    font-size: 18px;
  }

  .controls {
    display: none;
  }

  .card {
    gap: 10px;
    padding: 7px 9px;
  }

  .who-text small {
    display: none;
  }

  .close-hint {
    display: none;
  }
}

@media (max-height: 500px) and (orientation: landscape) {
  .hero {
    margin-bottom: 4vh;
  }

  h1 {
    font-size: clamp(44px, 8vw, 72px);
