export function createWorld(scene) {
  const terrain = buildTerrain()
  scene.add(terrain)

  const water = buildWater()
  scene.add(water)

  const foam = buildFoam()
  scene.add(foam)

  return {
    terrain,
    water,
    update(time) {
      water.material.uniforms.uTime.value = time
      foam.material.opacity = 0.26 + Math.sin(time * 0.9) * 0.06
    },
  }
}

function buildFoam() {
  const positions = []
  const y = 0.045
  const step = 1.4
  for (const side of [-1, 1]) {
    for (let x = -102; x <= 102; x += step) {
      if (heightAt(x, side * 30) > 0.08) continue
      let lo = 6
      let hi = 34
      for (let i = 0; i < 18; i++) {
        const mid = (lo + hi) / 2
        if (heightAt(x, side * mid) > 0.05) hi = mid
        else lo = mid
      }
      const zs = side * (lo + hi) / 2
      const z0 = zs - 0.55
      const z1 = zs + 0.55
      const x1 = x + step
      positions.push(
        x, y, z0, x1, y, z0, x, y, z1,
        x1, y, z0, x1, y, z1, x, y, z1,
      )
    }
  }
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
  const material = new THREE.MeshBasicMaterial({
    color: 0xeafff5,
    transparent: true,
    opacity: 0.28,
    depthWrite: false,
    side: THREE.DoubleSide,
    fog: true,
  })
  const mesh = new THREE.Mesh(geometry, material)
  mesh.renderOrder = 2
  return mesh
}

